float timeVar = ubuf.u_time * 1.5;
// Genera un "rumore" pseudo-casuale combinando le coordinate spaziali e il tempo
float noise = sin(pModel.x * 12.0 + timeVar) * cos(pModel.y * 15.0 - timeVar) * sin(pModel.z * 12.0);
noise = noise * 0.5 + 0.5; // Normalizza tra 0.0 e 1.0

vec3 magmaScuro = vec3(0.6, 0.0, 0.0); // Rosso cupo
vec3 magmaChiaro = vec3(1.0, 0.8, 0.0); // Giallo acceso

textureCol = mix(magmaScuro, magmaChiaro, noise);
